{% extends "base.html" %}
{% load erp_format %}
{% block content %}
{% include "components/page_header.html" with page_eyebrow="حسابداری" page_title=journal.description page_description=request.organization.name page_breadcrumb_label="اسناد حسابداری" page_breadcrumb_url="/accounting/journals/" only %}
<div class="mt-5 flex flex-wrap gap-2"><a class="erp-btn erp-btn--secondary" href="{% url 'accounting:journal_source' journal.pk %}">مشاهده منبع و مسیر ثبت</a>{% if journal.reverses %}<a class="erp-btn erp-btn--secondary" href="{% url 'accounting:journal_detail' journal.reverses.pk %}">سند اصلی</a>{% endif %}{% if journal.replaces %}<a class="erp-btn erp-btn--secondary" href="{% url 'accounting:journal_detail' journal.replaces.pk %}">سند جایگزین‌شده</a>{% endif %}{% if journal.adjusts %}<a class="erp-btn erp-btn--secondary" href="{% url 'accounting:journal_detail' journal.adjusts.pk %}">سند تعدیل‌شده</a>{% endif %}</div>
<section class="erp-surface mt-5 rounded-xl p-5"><dl class="grid gap-4 text-sm sm:grid-cols-3"><div><dt class="text-xs text-slate-500">شماره / وضعیت</dt><dd class="mt-1 font-semibold text-slate-900" dir="ltr">{{ journal.number|default:"—" }} · {{ journal.get_status_display }}</dd></div><div><dt class="text-xs text-slate-500">دوره مالی</dt><dd class="mt-1 font-medium">{{ journal.period }}</dd></div><div><dt class="text-xs text-slate-500">تهیه‌کننده</dt><dd class="mt-1 font-medium">{{ journal.prepared_by.user }}</dd></div><div><dt class="text-xs text-slate-500">کلید و نسخه منبع</dt><dd class="mt-1 break-all text-xs" dir="ltr">{{ journal.source_key }} · v{{ journal.source_version }}</dd></div><div><dt class="text-xs text-slate-500">قاعده ثبت</dt><dd class="mt-1 text-xs" dir="ltr">{{ journal.posting_rule_code|default:"—" }}{% if journal.posting_rule_version %} v{{ journal.posting_rule_version }}{% endif %}</dd></div><div><dt class="text-xs text-slate-500">تاریخ حسابداری</dt><dd class="mt-1" dir="ltr">{{ journal.accounting_date|jalali_date }}</dd></div>{% if journal.adjusts %}<div class="sm:col-span-3"><dt class="text-xs text-slate-500">دلیل تعدیل کنترل‌شده</dt><dd class="mt-1 font-medium">{{ journal.adjustment_reason }}</dd></div>{% endif %}</dl></section>
<section class="erp-surface mt-5 overflow-hidden rounded-xl"><div class="erp-panel-header"><div><h2 class="font-semibold text-slate-900">ردیف‌های سند</h2><p class="text-xs text-slate-500">ردیف‌های ارسال‌شده و قطعی فقط خواندنی‌اند.</p></div><span class="text-sm font-semibold tabular-nums" dir="ltr">{{ totals.debit|default:0|erp_number }} / {{ totals.credit|default:0|erp_number }}</span></div><div class="erp-table-wrap"><table class="w-full min-w-[860px] text-right text-sm"><thead><tr><th class="px-4 py-3">ردیف</th><th class="px-4 py-3">حساب</th><th class="px-4 py-3">بدهکار</th><th class="px-4 py-3">بستانکار</th><th class="px-4 py-3">ابعاد / شناسه منبع</th></tr></thead><tbody class="divide-y divide-slate-100">{% for line in lines %}<tr><td class="px-4 py-3">{{ line.line_number }}</td><td class="px-4 py-3">{% if line.account_snapshot %}{{ line.account_snapshot.code }} — {{ line.account_snapshot.name }}{% else %}{{ line.account }}{% endif %}</td><td class="px-4 py-3 tabular-nums" dir="ltr">{{ line.debit|erp_number }}</td><td class="px-4 py-3 tabular-nums" dir="ltr">{{ line.credit|erp_number }}</td><td class="px-4 py-3 text-xs text-slate-500" dir="ltr">{{ line.dimension_snapshot|default:"—" }} · {{ line.source_line_uuid }}</td></tr>{% endfor %}</tbody></table></div></section>
{% if journal.status == "draft" and "accounting.journals_prepare" in business_permission_codes %}<form class="erp-surface mt-5 rounded-xl p-5" method="post" action="{% url 'accounting:journal_line_add' journal.pk %}">{% csrf_token %}<h2 class="font-semibold text-slate-900">افزودن ردیف</h2><div class="mt-4 grid gap-4 sm:grid-cols-2">{% for field in line_form %}{% include "components/form_field.html" with field=field only %}{% endfor %}</div><button class="erp-btn erp-btn--primary mt-5">افزودن ردیف</button></form>{% endif %}
<section class="erp-surface mt-5 rounded-xl p-5"><h2 class="font-semibold text-slate-900">عملیات کنترل‌شده</h2><div class="mt-4 flex flex-wrap gap-3">{% if journal.status == "draft" and "accounting.journals_submit" in business_permission_codes %}<form method="post" action="{% url 'accounting:journal_submit' journal.pk %}">{% csrf_token %}<button class="erp-btn erp-btn--primary">ارسال برای تأیید</button></form>{% endif %}</div>{% if journal.status == "proposed" and "accounting.journals_post" in business_permission_codes %}<form class="mt-4 max-w-xl" method="post" action="{% url 'accounting:journal_post' journal.pk %}">{% csrf_token %}{% include "components/form_field.html" with field=reason_form.reason only %}<button class="erp-btn erp-btn--primary mt-3">تأیید و ثبت قطعی</button></form>{% endif %}{% if journal.status == "posted" and "accounting.journals_post" in business_permission_codes %}<form class="mt-4 max-w-xl" method="post" action="{% url 'accounting:journal_reverse' journal.pk %}">{% csrf_token %}<p class="mb-3 text-xs text-slate-500">برگشت نیازمند درخواست‌کننده مستقل و دلیل است.</p>{% for field in protected_reason_form %}{% include "components/form_field.html" with field=field only %}{% endfor %}<button class="erp-btn erp-btn--danger mt-3">ثبت برگشت محافظت‌شده</button></form>{% endif %}{% if journal.status == "posted" and "accounting.journals_prepare" in business_permission_codes %}<form class="mt-5 max-w-xl" method="post" action="{% url 'accounting:journal_replacement' journal.pk %}">{% csrf_token %}<h3 class="text-sm font-semibold">ایجاد سند جایگزین</h3><p class="mt-1 text-xs text-slate-500">سند جایگزین فقط پس از ثبت برگشت مرتبط قابل ایجاد است.</p>{% for field in replacement_form %}{% include "components/form_field.html" with field=field only %}{% endfor %}<button class="erp-btn erp-btn--secondary mt-3">ایجاد پیش‌نویس جایگزین</button></form>{% endif %}</section>
{% endblock %}

