{% extends "base.html" %}
{% load erp_format %}
{% block content %}
{% include "components/page_header.html" with page_eyebrow="حسابداری" page_title="ورودی مانده افتتاحیه" page_description=opening.source_reference only %}
<section class="erp-surface mt-5 rounded-xl p-5"><dl class="grid gap-4 text-sm sm:grid-cols-3"><div><dt class="text-xs text-slate-500">دوره</dt><dd class="mt-1">{{ opening.period }}</dd></div><div><dt class="text-xs text-slate-500">تاریخ برش</dt><dd class="mt-1" dir="ltr">{{ opening.cutoff_date }}</dd></div><div><dt class="text-xs text-slate-500">وضعیت</dt><dd class="mt-1">{{ opening.get_status_display }}</dd></div><div><dt class="text-xs text-slate-500">مدرک</dt><dd class="mt-1">{{ opening.evidence_reference }}</dd></div><div><dt class="text-xs text-slate-500">مرجع تطبیق</dt><dd class="mt-1">{{ opening.reconciliation_reference }}</dd></div>{% if opening.accepted_journal %}<div><dt class="text-xs text-slate-500">سند قطعی</dt><dd class="mt-1"><a class="font-semibold text-blue-700" href="{% url 'accounting:journal_detail' opening.accepted_journal.pk %}">مشاهده سند</a></dd></div>{% endif %}</dl></section>
<section class="erp-surface mt-5 overflow-hidden rounded-xl"><div class="erp-panel-header"><h2 class="font-semibold text-slate-900">ردیف‌های افتتاحیه</h2></div><div class="erp-table-wrap"><table class="w-full text-sm"><thead><tr><th class="px-4 py-3">حساب</th><th class="px-4 py-3">بدهکار</th><th class="px-4 py-3">بستانکار</th></tr></thead><tbody>{% for line in lines %}<tr><td class="px-4 py-3">{{ line.account }}</td><td class="px-4 py-3" dir="ltr">{{ line.debit|erp_number }}</td><td class="px-4 py-3" dir="ltr">{{ line.credit|erp_number }}</td></tr>{% endfor %}</tbody></table></div></section>
{% if opening.status == "draft" and "accounting.journals_prepare" in business_permission_codes %}<form class="erp-surface mt-5 rounded-xl p-5" method="post" action="{% url 'accounting:opening_line_add' opening.pk %}">{% csrf_token %}<h2 class="font-semibold">افزودن ردیف</h2><div class="mt-4 grid gap-4 sm:grid-cols-2">{% for field in line_form %}{% include "components/form_field.html" with field=field only %}{% endfor %}</div><button class="erp-btn erp-btn--primary mt-4">افزودن ردیف</button></form>{% endif %}
<section class="erp-surface mt-5 rounded-xl p-5">{% if opening.status == "draft" and "accounting.journals_submit" in business_permission_codes %}<form method="post" action="{% url 'accounting:opening_submit' opening.pk %}">{% csrf_token %}<button class="erp-btn erp-btn--primary">ارسال برای پذیرش</button></form>{% endif %}{% if opening.status == "proposed" and "accounting.journals_post" in business_permission_codes %}<form class="mt-4 max-w-xl" method="post" action="{% url 'accounting:opening_accept' opening.pk %}">{% csrf_token %}{% include "components/form_field.html" with field=reason_form.reason only %}<button class="erp-btn erp-btn--primary mt-3">پذیرش و ثبت قطعی</button></form>{% endif %}</section>
{% endblock %}

apps/billing/templates/billing/commercia.text:
{% extends "base.html" %}
{% block title %}{{ title }} | بنیرا{% endblock %}
{% block content %}
{% include "components/page_header.html" with page_breadcrumb_label="کنترل ضمانت و انطباق" page_breadcrumb_url="/billing/commercial-controls/" page_eyebrow="کنترل تجاری و شواهد" page_title=title page_description="فقط واقعیت قراردادی یا شاهد بازبینی‌شده ثبت می‌شود؛ نبود اختیار صریح، عملیات را متوقف می‌کند." only %}
