  <form method="post" class="grid gap-4 md:grid-cols-2">{% csrf_token %}
    {% for field in form %}<div{% if field.name == "reason" %} class="md:col-span-2"{% endif %}><label class="mb-1 block text-sm font-medium" for="{{ field.id_for_label }}">{{ field.label }}</label>{{ field }}{% if field.help_text %}<p class="mt-1 text-xs text-slate-500">{{ field.help_text }}</p>{% endif %}{% if field.errors %}<p class="mt-1 text-xs text-red-700">{{ field.errors|join:", " }}</p>{% endif %}</div>{% endfor %}
    {% if form.non_field_errors %}<div class="text-sm text-red-700 md:col-span-2">{{ form.non_field_errors }}</div>{% endif %}
