  </form>
</section>
{% endblock %}

{% extends "base.html" %}
{% block title %}{{ title }} | بنیرا{% endblock %}
{% block content %}
{% include "components/page_header.html" with page_breadcrumb_label="کنترل ضمانت و انطباق" page_breadcrumb_url="/billing/commercial-controls/" page_eyebrow=record.project.name page_title=title page_description=record.contract.contract_number only %}
<div class="mt-6 grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
  <section class="erp-surface rounded-xl p-4"><p class="text-xs text-slate-500">وضعیت</p><p class="mt-2">{% include "components/status_badge.html" with status=record.status label=record.get_status_display only %}</p></section>
  {% if kind == "guarantee" %}<section class="erp-surface rounded-xl p-4"><p class="text-xs text-slate-500">نوع و سمت</p><p class="mt-2 font-semibold">{{ record.get_guarantee_type_display }}</p><p class="text-xs text-slate-500">{{ record.get_exposure_side_display }}</p></section><section class="erp-surface rounded-xl p-4"><p class="text-xs text-slate-500">مبلغ اسمی</p><p class="mt-2 text-xl font-bold" dir="ltr">{{ record.amount }} {{ record.currency_code }}</p></section><section class="erp-surface rounded-xl p-4"><p class="text-xs text-slate-500">مرجع / نسخه</p><p class="mt-2 font-semibold" dir="ltr">{{ record.instrument_reference }} / {{ record.version }}</p></section>{% endif %}
  {% if kind == "compliance" %}<section class="erp-surface rounded-xl p-4"><p class="text-xs text-slate-500">نوع شاهد</p><p class="mt-2 font-semibold">{{ record.get_evidence_kind_display }}</p></section><section class="erp-surface rounded-xl p-4"><p class="text-xs text-slate-500">مرجع / نسخه</p><p class="mt-2 font-semibold" dir="ltr">{{ record.reference }} / {{ record.version }}</p></section><section class="erp-surface rounded-xl p-4"><p class="text-xs text-slate-500">مرجع صادرکننده</p><p class="mt-2 font-semibold">{{ record.issuing_authority }}</p></section>{% endif %}
  {% if kind == "release" %}<section class="erp-surface rounded-xl p-4"><p class="text-xs text-slate-500">مبلغ آزادسازی</p><p class="mt-2 text-xl font-bold" dir="ltr">{{ record.amount }} {{ record.currency_code }}</p></section><section class="erp-surface rounded-xl p-4"><p class="text-xs text-slate-500">مانده پیش از آزادسازی</p><p class="mt-2 font-semibold" dir="ltr">{{ record.available_amount_snapshot }}</p></section><section class="erp-surface rounded-xl p-4"><p class="text-xs text-slate-500">شماره / ویرایش</p><p class="mt-2 font-semibold" dir="ltr">{{ record.release_number }}-{{ record.revision_number }}</p></section>{% endif %}
</div>
<section class="erp-surface mt-6 rounded-xl p-5"><h2 class="font-semibold">شواهد و تاریخ‌های مؤثر</h2><dl class="mt-4 grid gap-4 text-sm sm:grid-cols-2 lg:grid-cols-4"><div><dt class="text-slate-500">قرارداد / طرف</dt><dd class="mt-1">{{ record.contract.contract_number }} — {{ record.party_identity_snapshot.display_name }}</dd></div>{% if kind == "guarantee" %}<div><dt class="text-slate-500">صادرکننده</dt><dd class="mt-1">{{ record.issuer_name }}</dd></div><div><dt class="text-slate-500">صدور / اثر / انقضا</dt><dd class="mt-1" dir="ltr">{{ record.issued_on }} / {{ record.effective_from }} / {{ record.expires_on|default:"—" }}</dd></div><div><dt class="text-slate-500">نسخه سند شاهد</dt><dd class="mt-1" dir="ltr">{{ record.evidence_document_version_id }}</dd></div>{% elif kind == "compliance" %}<div><dt class="text-slate-500">اثر / انقضا</dt><dd class="mt-1" dir="ltr">{{ record.effective_from }} / {{ record.expires_on|default:"—" }}</dd></div><div><dt class="text-slate-500">نسخه سند شاهد</dt><dd class="mt-1" dir="ltr">{{ record.document_version_id }}</dd></div>{% else %}<div><dt class="text-slate-500">نسخه شرایط</dt><dd class="mt-1" dir="ltr">{{ record.contract_term_version.version }}</dd></div><div><dt class="text-slate-500">کسور/آزادسازی قبلی</dt><dd class="mt-1" dir="ltr">{{ record.retained_total_snapshot }} / {{ record.prior_release_total_snapshot }}</dd></div><div><dt class="text-slate-500">مفاصاحساب پین‌شده</dt><dd class="mt-1" dir="ltr">{{ record.clearance_evidence_id|default:"—" }}</dd></div>{% endif %}</dl></section>
{% if record.predecessor_id or record.corrects_id %}<section class="mt-5 rounded-xl border border-amber-200 bg-amber-50 p-5 text-sm"><h2 class="font-semibold">زنجیره اصلاح</h2>{% if record.predecessor_id %}<p class="mt-2">نسخه پیشین: <span dir="ltr">{{ record.predecessor_id }}</span> — {{ record.get_revision_action_display }}</p>{% endif %}{% if record.corrects_id %}<p class="mt-2">آزادسازی مرجع: <span dir="ltr">{{ record.corrects_id }}</span> — {{ record.get_correction_kind_display }}</p>{% endif %}<p class="mt-1 text-slate-600">{{ record.revision_reason|default:record.correction_reason }}</p></section>{% endif %}
<div class="mt-6 flex flex-wrap gap-3">
  {% if record.status == "draft" %}<form method="post" action="{% if kind == 'guarantee' %}{% url 'billing:guarantee_submit' record.pk %}{% elif kind == 'compliance' %}{% url 'billing:compliance_evidence_submit' record.pk %}{% else %}{% url 'billing:retention_release_submit' record.pk %}{% endif %}">{% csrf_token %}<button class="erp-button-primary" type="submit">ارسال برای تأیید</button></form>{% endif %}
  {% if record.status == "submitted" %}<form class="flex flex-wrap gap-2" method="post" action="{% if kind == 'guarantee' %}{% url 'billing:guarantee_approve' record.pk %}{% elif kind == 'compliance' %}{% url 'billing:compliance_evidence_approve' record.pk %}{% else %}{% url 'billing:retention_release_approve' record.pk %}{% endif %}">{% csrf_token %}<input class="erp-input" name="reason" required placeholder="دلیل تأیید"><button class="erp-button-primary" type="submit">تأیید</button></form><form class="flex flex-wrap gap-2" method="post" action="{% if kind == 'guarantee' %}{% url 'billing:guarantee_return' record.pk %}{% elif kind == 'compliance' %}{% url 'billing:compliance_evidence_return' record.pk %}{% else %}{% url 'billing:retention_release_return' record.pk %}{% endif %}">{% csrf_token %}<input class="erp-input" name="reason" required placeholder="دلیل بازگردانی"><button class="erp-button-secondary" type="submit">بازگردانی</button></form>{% endif %}
  {% if "work_items.view" in business_permission_codes %}<a class="erp-button-secondary" href="{% url 'workflows:workbench' %}">کارتابل تأییدها</a>{% endif %}
</div>
{% if kind == "guarantee" and record.status == "active" or kind == "guarantee" and record.status == "expired" or kind == "compliance" and record.status == "approved" or kind == "compliance" and record.status == "expired" or kind == "release" and record.status == "approved" %}<section class="erp-surface mt-6 rounded-xl border-r-4 border-amber-400 p-5"><h2 class="font-semibold">نسخه پیوندخورده</h2><p class="mt-2 text-sm text-slate-600">نسخه نهایی بازنویسی نمی‌شود. اصلاح، تمدید، آزادسازی یا ابطال پس از گردش تأیید، سابقه را به‌صورت پیوندخورده تکمیل می‌کند.</p><form method="post" action="{% if kind == 'guarantee' %}{% url 'billing:guarantee_revise' record.pk %}{% elif kind == 'compliance' %}{% url 'billing:compliance_evidence_revise' record.pk %}{% else %}{% url 'billing:retention_release_correct' record.pk %}{% endif %}" class="mt-4 grid gap-4 md:grid-cols-2">{% csrf_token %}{% for field in revision_form %}<div><label class="mb-1 block text-sm font-medium" for="{{ field.id_for_label }}">{{ field.label }}</label>{{ field }}{% if field.errors %}<p class="mt-1 text-xs text-red-700">{{ field.errors|join:", " }}</p>{% endif %}</div>{% endfor %}<button class="erp-button-secondary md:col-span-2" type="submit">ایجاد نسخه جدید</button></form></section>{% endif %}
{% endblock %}

apps/billing/templates/billing/payable_f.text:
{% extends "base.html" %}
{% block title %}{{ title }} | بنیرا{% endblock %}
{% block content %}
{% include "components/page_header.html" with page_eyebrow="کنترل تجاری پرداختنی" page_title=title page_description="اطلاعات فقط در دامنه سازمان و پروژه فعال ثبت می‌شود." only %}
<section class="erp-surface mt-6 rounded-xl p-5"><form method="post" class="grid gap-4 md:grid-cols-2">{% csrf_token %}{% for field in form %}<div><label class="mb-1 block text-sm font-medium" for="{{ field.id_for_label }}">{{ field.label }}</label>{{ field }}{% if field.errors %}<p class="mt-1 text-xs text-red-700">{{ field.errors|join:", " }}</p>{% endif %}</div>{% endfor %}{% if form.non_field_errors %}<div class="text-sm text-red-700 md:col-span-2">{{ form.non_field_errors }}</div>{% endif %}<button class="erp-button-primary md:col-span-2" type="submit">ثبت</button></form></section>
{% endblock %}

templates/documents/upload.html.text:
{% extends "base.html" %}
{% block title %}ایجاد سند | سامانه مدیریت ساخت{% endblock %}
{% block content %}
<div class="mx-auto max-w-4xl"><p class="text-xs font-semibold text-blue-600">اسناد</p><h1 class="mt-1 text-2xl font-bold text-slate-950 sm:text-3xl">ایجاد سند</h1><p class="mt-1 text-sm text-slate-500">فایل خصوصی PDF، JPEG یا PNG تا ۱۰ مگابایت به‌عنوان نسخه اول ذخیره می‌شود.</p>
<form class="erp-surface mt-6 space-y-6 rounded-xl p-5 sm:p-6" method="post" enctype="multipart/form-data">{% csrf_token %}{% include "components/form_errors.html" with form=form only %}
  <section><h2 class="text-sm font-bold">مشخصات سند</h2><div class="mt-4 grid gap-4 md:grid-cols-2">{% include "components/form_field.html" with field=form.document_type only %}{% include "components/form_field.html" with field=form.title only %}{% include "components/form_field.html" with field=form.category only %}{% include "components/form_field.html" with field=form.confidentiality only %}{% include "components/form_field.html" with field=form.access_expires_at only %}{% include "components/form_field.html" with field=form.reference only %}</div><div class="mt-4">{% include "components/form_field.html" with field=form.description only %}</div></section>
  <section class="border-t border-slate-100 pt-5"><h2 class="text-sm font-bold">موجودیت مرتبط</h2><p class="mt-1 text-xs text-slate-500">دقیقاً یکی را انتخاب کنید؛ پس از ایجاد می‌توان ارتباط‌های بیشتری افزود.</p><div class="mt-4 grid gap-4 md:grid-cols-2">{% include "components/form_field.html" with field=form.project only %}{% include "components/form_field.html" with field=form.contract only %}{% include "components/form_field.html" with field=form.estimate only %}{% include "components/form_field.html" with field=form.expense only %}{% include "components/form_field.html" with field=form.treasury_movement only %}{% include "components/form_field.html" with field=form.daily_report only %}</div></section>
  <section class="border-t border-slate-100 pt-5"><h2 class="text-sm font-bold">نسخه اول</h2><div class="mt-4">{% include "components/form_field.html" with field=form.file only %}</div></section>
  <div class="flex flex-col-reverse gap-2 border-t border-slate-100 pt-5 sm:flex-row sm:justify-end"><a class="h-10 px-4 text-center text-sm font-semibold leading-10 text-slate-600" href="{% url 'documents:list' %}">انصراف</a><button class="h-10 rounded-lg bg-blue-600 px-4 text-sm font-semibold text-white" type="submit">ایجاد سند</button></div>
</form></div>
{% endblock %}

templates/documents/detail.html.text:
{% extends "base.html" %}
{% block title %}{{ document.title }} | سامانه مدیریت ساخت{% endblock %}
{% block content %}
<nav class="text-xs text-slate-400"><a href="{% url 'documents:list' %}">اسناد</a> / <span>{{ document.title }}</span></nav>
<div class="mt-4 flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between"><div class="min-w-0"><p class="text-xs font-semibold text-blue-600">{{ document.get_document_type_display }} · {{ document.get_confidentiality_display }} · نسخه {{ document.current_version.version_number }}</p><h1 class="mt-1 truncate text-2xl font-bold text-slate-950 sm:text-3xl">{{ document.title }}</h1><p class="mt-1 text-xs text-slate-500" dir="ltr">{{ document.document_number }}{% if document.reference %} · {{ document.reference }}{% endif %}</p>{% if document.current_version.is_available %}<p class="mt-1 text-xs font-semibold text-emerald-700">نسخه جاری قابل استفاده است.</p>{% else %}<p class="mt-1 text-xs font-semibold text-amber-700">نسخه جاری قرنطینه یا ارزیابی‌نشده است.</p>{% endif %}</div>{% if "documents.download" in business_permission_codes and document.current_version.is_available %}<a class="h-10 rounded-lg bg-blue-600 px-4 text-sm font-semibold leading-10 text-white" href="{% url 'documents:download' document.id %}">دریافت نسخه جاری</a>{% endif %}</div>
{% if document.description %}<p class="erp-surface mt-5 rounded-xl p-4 text-sm text-slate-600">{{ document.description }}</p>{% endif %}
<div class="mt-5 grid gap-5 lg:grid-cols-2">
  <section class="erp-surface rounded-xl p-5"><h2 class="text-sm font-bold">ارتباط‌های سند</h2><ul class="mt-4 divide-y divide-slate-100 text-sm">{% for link in document.links.all %}<li class="flex justify-between gap-4 py-3"><span class="text-slate-500">{{ link.target_type }}</span><span>{{ link.target }}</span></li>{% endfor %}</ul></section>
  <section class="erp-surface rounded-xl p-5"><h2 class="text-sm font-bold">تاریخچه نسخه‌ها</h2><div class="mt-4 divide-y divide-slate-100">{% for version in document.versions.all %}<div class="flex items-center justify-between gap-4 py-3 text-sm"><div><p class="font-semibold" dir="ltr">v{{ version.version_number }} · {{ version.original_file_name }}</p><p class="mt-1 text-[11px] text-slate-500"><span dir="ltr">{{ version.file_size }}</span> بایت · {{ version.created_at }}</p>{% if version.is_available %}<p class="mt-1 text-[11px] font-semibold text-emerald-700">قابل استفاده</p>{% else %}<p class="mt-1 text-[11px] font-semibold text-amber-700">غیرقابل استفاده تا ارزیابی پاک</p>{% endif %}</div>{% if "documents.download" in business_permission_codes and version.is_available %}<a class="text-xs font-semibold text-blue-700" href="{% url 'documents:version-download' document.id version.id %}">دریافت</a>{% endif %}</div>{% endfor %}</div></section>
</div>
<div class="mt-5 grid gap-5 lg:grid-cols-2"><section class="erp-surface rounded-xl p-5"><h2 class="text-sm font-bold">تعهدهای نگهداری</h2><ul class="mt-3 space-y-2 text-xs text-slate-600">{% for item in document.retention_applications.all %}<li>{{ item.policy_version.policy.name }} · {% if item.retention_until %}تا {{ item.retention_until }}{% else %}مدت نامشخص؛ غیرقابل امحا{% endif %}</li>{% empty %}<li>سیاست نگهداری اعمال نشده؛ امحا مسدود است.</li>{% endfor %}</ul></section><section class="erp-surface rounded-xl p-5"><h2 class="text-sm font-bold">نگهداری حقوقی</h2><ul class="mt-3 space-y-2 text-xs text-slate-600">{% for hold in document.legal_holds.all %}<li>{{ hold.reason }} · {% if hold.released_at %}آزادشده{% else %}فعال{% endif %}</li>{% empty %}<li>نگهداری حقوقی ثبت نشده است.</li>{% endfor %}</ul></section></div>
{% if "documents.upload" in business_permission_codes %}
<div class="mt-5 grid gap-5 lg:grid-cols-2">
  <form class="erp-surface space-y-4 rounded-xl p-5" method="post" enctype="multipart/form-data" action="{% url 'documents:version-add' document.id %}">{% csrf_token %}<h2 class="text-sm font-bold">افزودن نسخه</h2>{% include "components/form_errors.html" with form=version_form only %}{% include "components/form_field.html" with field=version_form.file only %}<button class="h-10 rounded-lg bg-blue-600 px-4 text-sm font-semibold text-white" type="submit">ثبت نسخه جدید</button></form>
  <form class="erp-surface space-y-4 rounded-xl p-5" method="post" action="{% url 'documents:link-add' document.id %}">{% csrf_token %}<h2 class="text-sm font-bold">افزودن ارتباط</h2><p class="text-xs text-slate-500">دقیقاً یک target جدید انتخاب کنید.</p>{% include "components/form_errors.html" with form=link_form only %}<div class="grid gap-3 md:grid-cols-2">{% include "components/form_field.html" with field=link_form.project only %}{% include "components/form_field.html" with field=link_form.contract only %}{% include "components/form_field.html" with field=link_form.estimate only %}{% include "components/form_field.html" with field=link_form.expense only %}{% include "components/form_field.html" with field=link_form.treasury_movement only %}{% include "components/form_field.html" with field=link_form.daily_report only %}</div><button class="h-10 rounded-lg border border-blue-200 px-4 text-sm font-semibold text-blue-700" type="submit">ثبت ارتباط</button></form>
</div>{% endif %}
{% if "documents.archive" in business_permission_codes %}<form class="erp-surface mt-5 max-w-2xl space-y-4 rounded-xl border-red-100 p-5" method="post" action="{% url 'documents:archive' document.id %}">{% csrf_token %}<div><h2 class="text-sm font-bold">بایگانی سند</h2><p class="mt-1 text-xs text-slate-500">تمام نسخه‌ها، لینک‌ها و ردپای ممیزی حفظ می‌شوند.</p></div>{% include "components/form_errors.html" with form=archive_form only %}{% include "components/form_field.html" with field=archive_form.reason only %}<button class="h-10 rounded-lg border border-red-200 px-4 text-sm font-semibold text-red-700" type="submit">بایگانی سند</button></form>{% endif %}
{% endblock %}

templates/workforce/employee_form.html.text:
{% extends "base.html" %}
{% block title %}ثبت کارمند | سامانه مدیریت ساخت{% endblock %}
{% block content %}
{% include "components/page_header.html" with page_eyebrow="منابع انسانی" page_title="ثبت کارمند" page_description="روش ثبت را انتخاب کنید و فقط اطلاعات لازم را وارد کنید." only %}

<form class="erp-surface mt-6 max-w-4xl rounded-xl p-5" method="post">
    {% csrf_token %}
    {% include "components/form_errors.html" with form=form only %}

    <fieldset>
        <legend class="text-sm font-bold text-slate-900">روش ثبت کارمند</legend>
        <div class="mt-3 grid gap-3 sm:grid-cols-2">
            {% for choice in form.source_type %}
            <label class="flex cursor-pointer items-start gap-3 rounded-xl border border-slate-200 p-4 transition hover:border-blue-300 hover:bg-blue-50/40" data-registration-card>
                {{ choice.tag }}
                <span>
                    <span class="block text-sm font-bold text-slate-900">{{ choice.choice_label }}</span>
                    <span class="mt-1 block text-xs leading-6 text-slate-500">
                        {% if choice.data.value == "existing_account" %}انتخاب حساب کاربری و فقط ورود اطلاعات شرکتی{% else %}ورود مشخصات کامل کارمند{% endif %}
                    </span>
                </span>
            </label>
            {% endfor %}
        </div>
        {% if form.source_type.errors %}<div class="mt-2 text-xs font-medium text-red-700">{{ form.source_type.errors }}</div>{% endif %}
    </fieldset>

    <section id="account-fields" class="mt-5 hidden">
        <h2 class="text-sm font-bold text-slate-900">حساب کاربری</h2>
        <p class="mt-1 text-xs leading-6 text-slate-500">اطلاعات مشترک از حساب انتخاب‌شده دریافت می‌شود و نیازی به ورود دوباره آن‌ها نیست.</p>
        <div class="mt-4">{% include "components/form_field.html" with field=form.user only %}</div>
        {% if can_link_account and not form.fields.user.queryset %}<p class="mt-3 rounded-lg border border-amber-200 bg-amber-50 p-3 text-xs leading-6 text-amber-800">حساب فعال و بدون پرونده کارمندی در این شرکت وجود ندارد.</p>{% endif %}
    </section>

    <section id="personal-fields" class="mt-5">
        <h2 class="text-sm font-bold text-slate-900">مشخصات فردی</h2>
        <div class="mt-4 grid gap-4 sm:grid-cols-2">
            {% include "components/form_field.html" with field=form.first_name only %}
            {% include "components/form_field.html" with field=form.last_name only %}
            {% include "components/form_field.html" with field=form.email only %}
            {% include "components/form_field.html" with field=form.phone_number only %}
        </div>
    </section>

    <section class="mt-5">
        <h2 class="text-sm font-bold text-slate-900">اطلاعات شرکتی</h2>
        <div class="mt-4 grid gap-4 sm:grid-cols-2">
            {% include "components/form_field.html" with field=form.employee_number only %}
            {% include "components/form_field.html" with field=form.department only %}
            {% include "components/form_field.html" with field=form.position only %}
            {% include "components/form_field.html" with field=form.work_team only %}
            {% include "components/form_field.html" with field=form.hire_date only %}
        </div>
    </section>
    <div class="mt-6 flex gap-3"><button class="erp-btn erp-btn--primary" type="submit">ثبت</button><a class="erp-btn erp-btn--secondary" href="{% url 'workforce:employee_list' %}">انصراف</a></div>
</form>
<script>
(() => {
    const sourceTypes = document.querySelectorAll('input[name="source_type"]');
    const registrationCards = document.querySelectorAll("[data-registration-card]");
    const accountFields = document.getElementById("account-fields");
    const personalFields = document.getElementById("personal-fields");
    const account = document.getElementById("id_user");
    const department = document.getElementById("id_department");
    const position = document.getElementById("id_position");
    const personalInputs = ["first_name", "last_name", "email", "phone_number"]
        .map((name) => document.getElementById(`id_${name}`))
        .filter(Boolean);

    const updateRegistrationMode = () => {
        const selected = document.querySelector('input[name="source_type"]:checked');
        const fromAccount = selected?.value === "existing_account";
        accountFields?.classList.toggle("hidden", !fromAccount);
        personalFields?.classList.toggle("hidden", fromAccount);
        if (account) account.disabled = !fromAccount;
        for (const input of personalInputs) input.disabled = fromAccount;
        for (const card of registrationCards) {
            const checked = card.querySelector('input[name="source_type"]')?.checked;
            card.classList.toggle("border-blue-500", Boolean(checked));
            card.classList.toggle("bg-blue-50", Boolean(checked));
        }
    };
    for (const input of sourceTypes) input.addEventListener("change", updateRegistrationMode);
    updateRegistrationMode();

    if (department && position) {
        const positionEndpoint = "{% url 'workforce:employee_positions' %}";
        department.addEventListener("change", async () => {
            const departmentId = department.value;
            position.innerHTML = '<option value="">در حال دریافت سمت‌ها…</option>';
            position.disabled = true;
            try {
                const response = await fetch(`${positionEndpoint}?department=${encodeURIComponent(departmentId)}`, {credentials: "same-origin"});
                if (!response.ok) throw new Error("Unable to load positions.");
                position.innerHTML = await response.text();
                position.disabled = false;
            } catch (_) {
                position.innerHTML = '<option value="">دریافت سمت‌ها ناموفق بود</option>';
            }
        });
    }
})();
</script>
{% endblock %}

